// キーエンス現場保全ログ: 競合相見積もりを即死させる「ライン停止損害試算」ロジック
function calculateDowntimeBleed(hourlyOutputUnits: number, unitGrossProfit: number, workerCount: number) {
  const lineBleedPerMinute = (hourlyOutputUnits * unitGrossProfit + workerCount * 5000) / 60;
  // 例: 1分停止＝8.5万円蒸発。他社センサー（納期2週間・定価8万円）vs キーエンス（当日納品・定価35万円）
  return {
    lossPerMinute: Math.round(lineBleedPerMinute),
    twoWeekWaitingLoss: Math.round(lineBleedPerMinute * 60 * 8 * 14), // 納期2週間の損失＝約5,700万円
    keyencePremiumJustification: "35万円の定価は、5,700万円の蒸発を防ぐ『保険代』として0.1秒で稟議承認される"
  };
}
