// Carrd現場保全配管: サーバー負荷をゼロにする静的HTMLコンパイル ＆ AWS S3無人デプロイ
import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';

export async function deploySinglePageSite({ siteId, docModel, isProUser }) {
  // 1. サーバー動的処理を完全排除。純粋な静的HTML/CSSのみに凝縮（インフラ月額原価: 0.0001円/サイト）
  const staticHtml = compileToStaticHtml(docModel, {
    footerBadge: !isProUser, // 無料プラン利用者のサイト全件に「Made with Carrd」を強制注入し無料集客
    customDomain: isProUser ? docModel.domain : null
  });

  // 2. AWS S3へPutObject ➔ Cloudflare CDNで全地球キャッシュ（何百万アクセス来てもサーバー落ちゼロ）
  await s3.send(new PutObjectCommand({
    Bucket: 'sites.carrd.co',
    Key: `${siteId}/index.html`,
    Body: staticHtml,
    ContentType: 'text/html; charset=utf-8',
    CacheControl: 'public, max-age=300'
  }));
}

// Linear現場保全配管: サーバー往復を待たずに0msでUIを確定させるローカルファーストSync
export class LocalFirstSyncEngine {
  constructor(private localDb: SQLiteDatabase, private wsClient: WebSocket) {}

  async updateIssueStatus(issueId: string, newStatus: string) {
    // 1. サーバー応答を一切待たず、ローカルSQLite/IndexedDBを0msで即時書き換え（操作感50ms未満）
    await this.localDb.exec("UPDATE issues SET status = ? WHERE id = ?", [newStatus, issueId]);
    this.emitUiUpdate(issueId); // UIは即座に完了状態を描画

    // 2. ミューテーション差分をバックグラウンドWebSocketで非同期同期（オフラインでも失われない）
    this.wsClient.send(JSON.stringify({
      op: 'UPDATE_ISSUE',
      payload: { id: issueId, status: newStatus, clientTimestamp: Date.now() }
    }));
  }
}

