// タスク遅延イベントを検知して後続タスクを自動リスケジュールする配管
export function rescheduleDependentTasks(delayedTaskId: string, delayHours: number) {
  const downstream = getDownstreamTasks(delayedTaskId);
  return downstream.map(task => ({ ...task, start: addHours(task.start, delayHours), status: "AUTO_ADJUSTED" }));
}

